import{_ as e,c as a,o as s,aM as i}from"./chunks/framework.kKeYZnSg.js";const l="/fe-handbook/assets/image.DfwCQocK.webp",o="/fe-handbook/assets/image-20260607142411671.BZ5XBn-o.png",n="/fe-handbook/assets/image-20260607142442700.Z1NvM1g3.png",f=JSON.parse('{"title":"HTTP Caching","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/network/http/caching.md","filePath":"fundamentals/network/http/caching.md","lastUpdated":1787499056000}'),r={name:"fundamentals/network/http/caching.md"};function p(c,t,h,d,g,k){return s(),a("div",null,t[0]||(t[0]=[i('<h1 id="http-caching" tabindex="-1">HTTP Caching <a class="header-anchor" href="#http-caching" aria-label="Permalink to &quot;HTTP Caching&quot;">​</a></h1><ul><li>强缓存 Strong cache</li><li>协商缓存 Negotiation cache</li></ul><blockquote><p>HTTP协议中规定使用GMT时间，也就是格林威治标准时间，而我们国家使用的是GMT+8时区，所以在HTTP头信息中的时间会比我们的正常时间早8个小时，但它一点都不影响HTTP缓存的正常工作。</p></blockquote><h2 id="缓存获取顺序" tabindex="-1">缓存获取顺序 <a class="header-anchor" href="#缓存获取顺序" aria-label="Permalink to &quot;缓存获取顺序&quot;">​</a></h2><blockquote><p>按照缓存顺序来讲，当一个资源准备加载时，浏览器会根据其<strong>三级缓存原理</strong>进行判断。</p><ol><li>浏览器会率先查找内存缓存，如果资源在内存中存在，那么直接从内存中加载</li><li>如果内存中没找到，接下去会去磁盘中查找，找到便从磁盘中获取</li><li>如果磁盘中也没有找到，那么就进行网络请求，并将请求后符合条件的资源存入内存和磁盘中</li></ol><p>浏览器内存缓存生效的前提下，JS 资源的执行加载时间会影响其是否被内存缓存</p><p>图片资源（非 base64）也有和 JS 资源同样的现象，而 CSS 资源比较与众不同，其被磁盘缓存的概率远大于被内存缓存。</p><p>当使用 preload 预加载资源后，笔者发现该资源一直会从磁盘缓存中读取，JS、CSS 及图片资源都有同样的表现，这主要还是和资源的渲染时机有关，在渲染机制还没有介入前的资源加载不会被内存缓存。</p><p>prefetch 则表示预提取，告诉浏览器加载下一页面可能会用到的资源，浏览器会利用空闲状态进行下载并将资源存储到缓存中。</p><p>比如：访问图片-&gt; 200 -&gt; 退出浏览器</p><p>再进来-&gt; 200(from disk cache) -&gt; 刷新 -&gt; 200(from memory cache)</p><p>我们可以打开一个新的tab页面，打开 &quot;Network&quot;，刷新一下，看到缓存的 <code>.js</code> 都是 &quot;from memory&quot;（<code>.css</code> 不会走 memory cache，都是 &quot;from disk&quot;）。</p><p>现在我们关闭当前tab（或关闭浏览器），重新再打开之前的 tab 时，缓存的 <code>.js</code> 都是 &quot;from disk&quot; 了。</p><p>因为当 <code>.js</code> 等资源被加载时，浏览器会先将其放入 <code>memory cache</code> 中，而当此页面tab被关闭时，浏览器会将此页面的 <code>memory cache</code> 中的缓存文件转存到 <code>disk cache</code> 中持久化存储。</p></blockquote><p><a href="https://nuxtjs-v316.vercel.app/" target="_blank" rel="nofollow noopener noreferrer">https://nuxtjs-v316.vercel.app/</a></p><p><img src="'+l+'" alt="image"></p><h2 id="不同交互影响浏览器如何处理页面资源" tabindex="-1">不同交互影响浏览器如何处理页面资源 <a class="header-anchor" href="#不同交互影响浏览器如何处理页面资源" aria-label="Permalink to &quot;不同交互影响浏览器如何处理页面资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">地址栏回车 / 点击链接 / 前进后退</th><th style="text-align:left;">刷新按钮 / 按 F5 / Ctrl+R</th><th>Ctrl+F5 / Ctrl+Shift+R</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心行为</strong></td><td style="text-align:left;"><strong>导航（Navigate）</strong></td><td style="text-align:left;"><strong>重载（Reload）</strong></td><td><strong>强制刷新</strong></td></tr><tr><td style="text-align:left;"><strong>对强缓存的处理</strong></td><td style="text-align:left;"><strong>优先使用缓存</strong>。如果资源仍在有效期内，浏览器会直接读取本地缓存，不发起网络请求。</td><td style="text-align:left;"><strong>先重新校验</strong>。即使资源还没过期，浏览器也会先向服务器确认资源是否更新。</td><td><strong>忽略本地缓存</strong>。直接重新请求资源。</td></tr><tr><td style="text-align:left;"><strong>发给服务器的请求头</strong></td><td style="text-align:left;"><strong>通常不额外添加</strong>。只有在缓存过期后，才会携带 <code>If-Modified-Since</code> 或 <code>If-None-Match</code> 等头部进行协商缓存验证。</td><td style="text-align:left;"><strong>通常会带上 <code>Cache-Control: max-age=0</code></strong>。表示不要直接信任缓存，需要向服务器重新确认资源是否更新；必要时也会携带 <code>If-Modified-Since</code> 或 <code>If-None-Match</code>。</td><td><strong><code>Cache-Control: no-cache</code>、<code>Pragma: no-cache</code></strong>，要求尽量不要使用缓存。</td></tr><tr><td style="text-align:left;"><strong>网络面板显示</strong></td><td style="text-align:left;"><code>200 (from memory/disk cache)</code>。表示资源直接从内存或磁盘缓存中读取，没有发起网络请求。</td><td style="text-align:left;">可能显示 <code>304 Not Modified</code> 或 <code>200 OK</code>。表示浏览器已经发起请求，并根据服务器返回结果决定是否复用缓存。</td><td>通常显示 <code>200 OK</code>，因为资源会重新从服务器获取。</td></tr></tbody></table><p><img src="'+o+'" alt="image-20260607142411671"></p><p><img src="'+n+`" alt="image-20260607142442700"></p><p>注意，上面的规则主要针对<strong>当前被访问的资源</strong>。例如，HTML 页面里引入的 CSS 和 JS 作为子资源，也会按各自的缓存策略判断是否直接使用本地缓存。</p><p>如果在新标签页里直接访问某个 CSS 链接，那么这个 CSS 文件本身就成了“主资源”，它的行为也会和访问 HTML 时类似。</p><p>如果使用<strong>强制刷新</strong>，则通常会尽量跳过主文档和子资源的缓存，页面相关资源都会重新请求。</p><p>假设页面如下：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stylesheet&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/app.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/app.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li>情况 A：你在地址栏输入 /index.html <ul><li>index.html 作为主文档，浏览器按“导航”规则处理</li><li>app.css、app.js 作为子资源，各自判断是否能直接走缓存</li></ul></li><li>情况 B：你按 F5 <ul><li>浏览器优先把它当“重新加载当前页面”</li><li>index.html 往往会重新验证</li><li>但 app.css、app.js 仍可能直接命中本地缓存</li></ul></li><li>情况 C：你新开标签页直接访问 /app.css <ul><li>现在 app.css 自己成了主文档</li><li>它的行为就和访问 HTML 时一样</li></ul></li><li>情况 D：你按 Ctrl+F5 <ul><li>主文档和子资源都尽量跳过缓存</li><li>所以整个页面资源基本都会重新请求</li></ul></li></ul><h3 id="memory-cache-vs-disk-cache" tabindex="-1">Memory Cache vs Disk Cache <a class="header-anchor" href="#memory-cache-vs-disk-cache" aria-label="Permalink to &quot;Memory Cache vs Disk Cache&quot;">​</a></h3><ul><li>Memory Cache：浏览器内存缓存，存储在RAM中，访问速度快，但容量有限，浏览器关闭后会丢失。</li><li>Disk Cache：浏览器磁盘缓存，存储在硬盘中，访问速度较慢，但容量较大，浏览器关闭后仍然存在。</li><li>如何选择：浏览器会根据资源类型、大小、访问频率等因素自动决定将资源存储在内存缓存还是磁盘缓存中。一般来说，较小且频繁访问的资源更可能被存储在内存缓存中，而较大或不常访问的资源则更可能被存储在磁盘缓存中。开发者没有直接控制权。</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><p><a href="https://segmentfault.com/a/1190000007729685" target="_blank" rel="nofollow noopener noreferrer">https://segmentfault.com/a/1190000007729685</a></p></li><li><p><a href="https://blog.devgenius.io/web-application-performance-optimization-http-caching-791eeda4509e" target="_blank" rel="nofollow noopener noreferrer">https://blog.devgenius.io/web-application-performance-optimization-http-caching-791eeda4509e</a></p></li><li><p><a href="https://juejin.cn/post/7177568033316012088" target="_blank" rel="nofollow noopener noreferrer">https://juejin.cn/post/7177568033316012088</a></p></li><li><p><a href="https://www.cnblogs.com/developer-ios/p/14044834.html" target="_blank" rel="nofollow noopener noreferrer">https://www.cnblogs.com/developer-ios/p/14044834.html</a></p></li></ul>`,21)]))}const u=e(r,[["render",p]]);export{f as __pageData,u as default};
